import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Roof-laying Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/24-construction-roof-profile.md","filePath":"reference/24-construction-roof-profile.md","lastUpdated":1788414836000}'),i={name:"reference/24-construction-roof-profile.md"};function n(s,e,c,l,h,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="roof-laying-source-profile" tabindex="-1">Roof-laying Source Profile <a class="header-anchor" href="#roof-laying-source-profile" aria-label="Permalink to &quot;Roof-laying Source Profile&quot;">​</a></h1><h2 id="claim-and-authority" tabindex="-1">Claim and authority <a class="header-anchor" href="#claim-and-authority" aria-label="Permalink to &quot;Claim and authority&quot;">​</a></h2><p>The <code>construction_roof</code> activity is linked to <code>muhurta.construction_roof</code>. Its authority is B. V. Raman&#39;s <em>Muhurtha</em>, Chapter XII, &quot;Laying the Foundation,&quot; printed page 50 (PDF page 54 in the registered edition). Raman is a modern secondary authority, not scripture.</p><p>The passage treats house construction as distinct stages and says that the roofing should be done with Vrishabha or Tula rising. The implementation therefore admits only those two Lagnas.</p><h2 id="deliberate-limits" tabindex="-1">Deliberate limits <a class="header-anchor" href="#deliberate-limits" aria-label="Permalink to &quot;Deliberate limits&quot;">​</a></h2><p>This locator does not provide a roofing-specific weekday, Tithi, or Nakshatra list. The profile does not borrow the adjacent foundation rules for those dimensions. Its existing Panchaka-Nakshatra restriction comes from a separate project rule and does not inherit authority from this claim.</p><p>This distinction matters: a page-level citation is not permission to combine neighboring rules that the text assigns to different construction stages.</p><h2 id="surfaces-and-enforcement" tabindex="-1">Surfaces and enforcement <a class="header-anchor" href="#surfaces-and-enforcement" aria-label="Permalink to &quot;Surfaces and enforcement&quot;">​</a></h2><p>Python and MCP expose the stable claim ID and the same two-Lagna constraint. Contract tests pin the rule, verify that the MCP payload publishes it, and keep the provenance coverage report synchronized.</p>',9)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
